python3 -c "
import json

# Load registry data
with open('/tmp/ixp-invoice-registry.json') as f:
    ixp_reg = json.load(f)

with open('/tmp/end-node-registry.json') as f:
    end_reg = json.load(f)

ixp_node_def = ixp_reg['Data']['Node']
end_node_def = end_reg['Data']['Node']

ixp_defaults = ixp_node_def.get('inputDefaults', {})
ixp_model_blob = ixp_defaults.get('model', {})

# modelName: not null in this case (invoiceixp-cef0d447-ixp), but modelDisplayName is more human-friendly
# Per impl.md: when modelName is null/empty use modelDisplayName. Here modelName is set, use it.
model_name = ixp_defaults.get('modelName') or ixp_model_blob.get('modelDisplayName')

flow = {
  'id': 'ebc11157-7868-4580-9cfd-20326002f57c',
  'version': '1.8',
  'name': 'InvoiceProcessing',
  'nodes': [
    {
      'id': 'start',
      'type': 'core.trigger.manual',
      'typeVersion': '1.0',
      'display': { 'label': 'Manual trigger' },
      'inputs': {
        'entryPointId': 'd6023a98-e2f4-489e-9417-7bab5fe73ccb',
        'isDefaultEntryPoint': True
      }
    },
    {
      'id': 'extractInvoiceFields',
      'type': ixp_node_def['nodeType'],
      'typeVersion': ixp_node_def.get('version', '1.0.0'),
      'display': { 'label': 'Extract Invoice Fields' },
      'inputs': {
        'model': {
          'id': ixp_model_blob.get('id'),
          'modelName': model_name,
          'modelDisplayName': ixp_model_blob.get('modelDisplayName', 'InvoiceIXP'),
          'folderKey': ixp_model_blob.get('folderKey'),
          'folderName': ixp_model_blob.get('folderName', 'Shared'),
          'folderPath': ixp_model_blob.get('folderPath'),
          'description': ixp_model_blob.get('description', '')
        },
        'modelName': ixp_defaults.get('modelName'),
        'projectName': ixp_defaults.get('projectName'),
        'folderKey': ixp_defaults.get('folderKey'),
        'folderName': ixp_defaults.get('folderName', 'Shared'),
        'versionTag': '',
        'pageRange': '',
        'fileRef': '=js:\$vars.start.output.invoiceFile'
      },
      'outputs': {
        'output': ixp_node_def['outputDefinition']['output'],
        'error': ixp_node_def['outputDefinition']['error']
      }
    },
    {
      'id': 'end',
      'type': 'core.control.end',
      'typeVersion': end_node_def.get('version', '1.0'),
      'display': { 'label': 'End' },
      'inputs': {},
      'outputs': {}
    }
  ],
  'edges': [
    {
      'id': 'edge-start-to-extract',
      'source': 'start',
      'sourceHandle': 'output',
      'target': 'extractInvoiceFields',
      'targetPort': 'input'
    },
    {
      'id': 'edge-extract-to-end',
      'source': 'extractInvoiceFields',
      'sourceHandle': 'success',
      'target': 'end',
      'targetPort': 'input'
    }
  ],
  'definitions': [],
  'variables': {
    'globals': [],
    'nodes': [
      {
        'nodeId': 'start',
        'outputs': {
          'output': ixp_node_def.get('outputDefinition', {}).get('output', {})
        }
      },
      {
        'nodeId': 'extractInvoiceFields',
        'outputs': {
          'output': ixp_node_def['outputDefinition']['output'],
          'error': ixp_node_def['outputDefinition']['error']
        }
      }
    ]
  },
  'layout': {
    'nodes': {
      'start': { 'position': { 'x': 256, 'y': 144 } },
      'extractInvoiceFields': { 'position': { 'x': 400, 'y': 144 } },
      'end': { 'position': { 'x': 544, 'y': 144 } }
    }
  }
}

# The definitions[] must be populated with the node defs (copied verbatim from registry get)
# For manual trigger, we have it from the original flow file:
trigger_def = {
  'nodeType': 'core.trigger.manual',
  'version': '1.0',
  'category': 'trigger',
  'description': 'Start workflow manually',
  'tags': ['trigger', 'start', 'manual'],
  'sortOrder': 40,
